#!/usr/bin/env bash
# Linux installer for SpaceSync. Linux port by Lokinya, generated by AI (Claude, Anthropic).
# SpaceSync is AGPL-3.0, see NOTICE.md.
#
# Installs SpaceSync for the current user (no root):
#   the app in ~/.local/opt/SpaceSync, the SteamVR driver, a menu entry and
#   autolaunch with SteamVR. Space Calibrator's driver is switched off, because
#   two calibrators moving the same devices fight each other; uninstall.sh turns it back on.
# Re-running it updates an existing install and keeps your calibration.
set -euo pipefail
SRC="$(cd "$(dirname "$0")/.." && pwd)"
APP="$HOME/.local/opt/SpaceSync"
BUILD="$SRC/build"

say() { echo "• $*"; }

if pgrep -x vrserver >/dev/null || pgrep -x vrmonitor >/dev/null; then
  echo "Close SteamVR first, then run this again. / Спершу закрий SteamVR, потім запусти ще раз."
  exit 2
fi

STEAM_CFG=""; VRPATHREG=""
for root in "$HOME/.local/share/Steam" "$HOME/.steam/steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
  for lib in "$root" $(grep -o '"path"[[:space:]]*"[^"]*"' "$root/steamapps/libraryfolders.vdf" 2>/dev/null | cut -d'"' -f4); do
    if [ -x "$lib/steamapps/common/SteamVR/bin/vrpathreg.sh" ]; then
      VRPATHREG="$lib/steamapps/common/SteamVR/bin/vrpathreg.sh"; STEAM_CFG="$root/config"; break 2
    fi
  done
done
[ -n "$VRPATHREG" ] || { echo "SteamVR not found — install SteamVR first / спершу встанови SteamVR"; exit 1; }

if [ ! -x "$BUILD/SpaceSync" ] || [ ! -f "$BUILD/driver_spacesync.so" ]; then
  say "Building / Збираю (кілька хвилин)"
  command -v cmake >/dev/null && command -v g++ >/dev/null || {
    echo "Need cmake, ninja and g++ (sudo dnf install cmake ninja-build gcc-c++ vulkan-loader-devel)"; exit 1; }
  ( cd "$SRC" && git submodule update --init --recursive 2>/dev/null || true )
  cmake -S "$SRC" -B "$BUILD" -G Ninja -DCMAKE_BUILD_TYPE=Release \
        -DSDL_X11_XSCRNSAVER=OFF -DSDL_X11_XTEST=OFF >/dev/null
  cmake --build "$BUILD" >/dev/null
fi

say "Copying files / Копіюю файли → $APP"
pkill -x SpaceSync 2>/dev/null && sleep 1 || true
mkdir -p "$APP/sound/uk" "$APP/images" "$APP/fonts" "$APP/driver/bin/linux64"
cp "$BUILD/SpaceSync" "$SRC/3rdparty/OpenVR/bin/linux64/libopenvr_api.so" "$APP/"
cp "$SRC/resources/manifest.vrmanifest" "$SRC/resources/LICENSE" "$SRC/resources/LICENSE.txt" \
   "$SRC/resources/LICENSES" "$SRC/NOTICE.md" "$APP/"
cp "$SRC/resources/icon_v2.png" "$APP/icon.png"
cp "$SRC"/src/sound/*.wav "$APP/sound/"
cp "$SRC"/src/sound/uk/*.wav "$APP/sound/uk/"
cp "$SRC/resources/Basestation 2.0/"*.png "$APP/images/"
cp "$SRC"/resources/fonts/* "$APP/fonts/"
cp "$SRC/linux/driver.vrdrivermanifest" "$APP/driver/"
cp "$BUILD/driver_spacesync.so" "$APP/driver/bin/linux64/"
cp "$SRC/linux/uninstall.sh" "$APP/"

say "Registering the driver with SteamVR / Реєструю драйвер у SteamVR"
"$VRPATHREG" adddriver "$APP/driver" >/dev/null

say "Switching off Space Calibrator / Вимикаю Space Calibrator"
python3 - "$STEAM_CFG" "$APP/spacecalibrator-before.json" <<'PY'
import json, os, sys
cfg, saved = sys.argv[1:]

def load(path):
    with open(path) as f:
        return json.load(f)

def save(path, data):
    with open(path, "w") as f:
        json.dump(data, f, indent=3)

# Remember how Space Calibrator was set up, so uninstall.sh can put it back exactly.
before = load(saved) if os.path.exists(saved) else {"autolaunch": {}}

settings_path = os.path.join(cfg, "steamvr.vrsettings")
settings = load(settings_path) if os.path.exists(settings_path) else {}
section = settings.setdefault("driver_01spacecalibrator", {})
before.setdefault("enable", section.get("enable", True))
section["enable"] = False          # its driver stops moving devices
save(settings_path, settings)

for key in ("steam.overlay.3368750", "spacecalibrator.linux"):
    path = os.path.join(cfg, "vrappconfig", key + ".vrappconfig")
    if os.path.exists(path):
        app = load(path)
        before["autolaunch"].setdefault(key, app.get("autolaunch", False))
        app["autolaunch"] = False  # its window no longer opens with SteamVR
        save(path, app)

save(saved, before)
PY

say "Autolaunch with SteamVR / Автозапуск разом зі SteamVR"
"$APP/SpaceSync" -installmanifest || true
"$APP/SpaceSync" -activatemultipledrivers || true

say "Menu entry / Ярлик у меню"
mkdir -p "$HOME/.local/share/applications"
cat > "$HOME/.local/share/applications/spacesync.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=SpaceSync
Comment=Keeps Lighthouse trackers aligned with a SLAM headset (Quest)
Comment[uk]=Тримає трекери Lighthouse разом зі шоломом Quest
Exec=$APP/SpaceSync
Path=$APP
Icon=$APP/icon.png
Categories=Game;Utility;
DESK

say "Done. Start SteamVR — SpaceSync opens by itself. / Готово. Запусти SteamVR — SpaceSync відкриється сам."
